Here is the commit message:
drm/amdkfd: fix uint32 variable compared to less than zero

Currently the call to kfd_process_gpuidx_from_gpuid is returning an
int value and this is being assigned to a uint32_t variable gpuidx
and this is being checked for a negative error return which is always
going to be false. Fix this by making gpuidx an int32_t. This makes
gpuidx also type consistent with the use of gpuidx from the callers.

Addresses-Coverity: ("Unsigned compared against 0")
Fixes: cda0f85bfa5e ("drm/amdkfd: refine migration policy with xnack on")
Signed-off-by: Colin Ian King <colin.king@canonical.com>
Reviewed-by: Felix Kuehling <Felix.Kuehling@amd.com>
Signed-off-by: Felix Kuehling <Felix.Kuehling@amd.com>
Signed-off-by: Alex Deucher <alexander.deucher@amd.com>

Here is the root cause:
The bug was caused by assigning the return value of a function that returns an `int` (which can be negative) to a `uint32_t` variable. This led to incorrect comparisons against negative values, as the unsigned type can never represent negative numbers, resulting in logical errors in the code.

Here is the patch:
  */
 static int svm_range_validate_and_map(struct mm_struct *mm,
 				      struct svm_range *prange,
-				      uint32_t gpuidx, bool intr, bool wait)
+				      int32_t gpuidx, bool intr, bool wait)
 {
 	struct svm_validate_context ctx;
 	struct hmm_range *hmm_range;
 	int r = 0;

 	ctx.process = container_of(prange->svms, struct kfd_process, svms);
 	ctx.prange = prange;
 	ctx.intr = intr;

 	if (gpuidx < MAX_GPU_INSTANCE) {
 		bitmap_zero(ctx.bitmap, MAX_GPU_INSTANCE);
 		bitmap_set(ctx.bitmap, gpuidx, 1);
 	} else if (ctx.process->xnack_enabled) {
 		bitmap_copy(ctx.bitmap, prange->bitmap_aip, MAX_GPU_INSTANCE);

 		/* If prefetch range to GPU, or GPU retry fault migrate range to
 		 * GPU, which has ACCESS attribute to the range, create mapping
 		 * on that GPU.
 		 */
 		if (prange->actual_loc) {
 			gpuidx = kfd_process_gpuidx_from_gpuid(ctx.process,
 							prange->actual_loc);
 			if (gpuidx < 0) {
 				WARN_ONCE(1, "failed get device by id 0x%x\n",
 					 prange->actual_loc);
 				return -EINVAL;
 			}
 			if (test_bit(gpuidx, prange->bitmap_access))
 				bitmap_set(ctx.bitmap, gpuidx, 1);
 		}
 	} else {
 		bitmap_or(ctx.bitmap, prange->bitmap_access,
 			  prange->bitmap_aip, MAX_GPU_INSTANCE);
 	}

 	if (bitmap_empty(ctx.bitmap, MAX_GPU_INSTANCE))
 		return 0;

 	if (prange->actual_loc && !prange->ttm_res) {
 		/* This should never happen. actual_loc gets set by
 		 * svm_migrate_ram_to_vram after allocating a BO.
 		 */
 		WARN(1, "VRAM BO missing during validation\n");
 		return -EINVAL;
 	}

 	svm_range_reserve_bos(&ctx);

 	if (!prange->actual_loc) {
 		r = amdgpu_hmm_range_get_pages(&prange->notifier, mm, NULL,
 					       prange->start << PAGE_SHIFT,
 					       prange->npages, &hmm_range,
 					       false, true);
 		if (r) {
 			pr_debug("failed %d to get svm range pages\n", r);
 			goto unreserve_out;
 		}

 		r = svm_range_dma_map(prange, ctx.bitmap,
 				      hmm_range->hmm_pfns);
 		if (r) {
 			pr_debug("failed %d to dma map range\n", r);
 			goto unreserve_out;
 		}

 		prange->validated_once = true;
 	}

 	svm_range_lock(prange);
 	if (!prange->actual_loc) {
 		if (amdgpu_hmm_range_get_pages_done(hmm_range)) {
 			r = -EAGAIN;
 			goto unlock_out;
 		}
 	}
 	if (!list_empty(&prange->child_list)) {
 		r = -EAGAIN;
 		goto unlock_out;
 	}

 	r = svm_range_map_to_gpus(prange, ctx.bitmap, wait);

 unlock_out:
 	svm_range_unlock(prange);
 unreserve_out:
 	svm_range_unreserve_bos(&ctx);

 	if (!r)
 		prange->validate_timestamp = ktime_to_us(ktime_get());

 	return r;
 }



